import json,re
r='rounds/round-002/'
facts=json.load(open('snapshot/facts.json'))
fid={f['fact_id']:f for f in facts['facts']}
hist=json.load(open(r+'computed/history.json'))
rec={}
for line,obs in hist['lines'].items():
  for o in obs: rec[o['id']]=(line,o)
vals=json.load(open(r+'computed/values.json'))
def resolve(i,depth=0):
  if i in fid: f=fid[i]; return f"{i} {f['concept']} {f['start']}..{f['end']} {f['val']} {f['form']} {f['accn']}"
  if i in rec:
    line,o=rec[i]; sub=[resolve(c,depth+1) for c in o['components']]
    ok=all(not s.startswith('UNRES') for s in sub)
    return f"{i} [{line} {o.get('start')}..{o['end']} {o['val']} {o['formula']}] <- " + ' ; '.join(sub)
  return 'UNRES '+i
for k,v in vals.items():
  for s in v['sources']:
    if re.match(r'^[FDS]-',s): print(k,':',resolve(s))
for line in ['short_term_investments','debt','cash','diluted_shares','shares_outstanding']:
  if line in hist['lines']: print(line, hist['lines'][line][-1])
print(hist['quarters'][-2:])
EOF

